interface.definition:
a!localVariables(
  local!groupsForUser: #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6717244"(
    groups: getgroupsformemberuser(loggedInUser()),
    user: loggedInUser()
  ),
  local!list1: #"urn:appian:function:v1:a:update"(
    local!groupsForUser,
    wherecontains(
      { "CAW WRPPP CoS", "CAW ERPPP CoS" },
      touniformstring(local!groupsForUser)
    ),
    "CAW APPP CoS"
  ),
  local!list2: #"urn:appian:function:v1:a:update"(
    local!list1,
    wherecontains(
      { "CAW RPPP" },
      touniformstring(local!list1)
    ),
    "CAW APPP"
  ),
  local!finalGroupsForUser: union(local!list2,local!list2),
  #"SYSTEM_SYSRULES_billboardLayout_v1"(
    backgroundColor: "#0b5394",
    height: if(
      count(local!groupsForUser) = 1,
      "SHORT_PLUS",
      "MEDIUM"
    ),
    overlay: #"SYSTEM_SYSRULES_barOverlay"(
      contents: {
        #"SYSTEM_SYSRULES_columnsLayout"(
          columns: {
            #"SYSTEM_SYSRULES_columnLayout"(
              contents: {
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: {
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_sideBySideLayout"(
                          items: {
                            #"SYSTEM_SYSRULES_sideBySideItem"(
                              item: #"SYSTEM_SYSRULES_imageField_v1"(
                                images: { #"SYSTEM_SYSRULES_userImage"(user: loggedInUser()) },
                                size: "MEDIUM",
                                isThumbnail: false,
                                style: "AVATAR"
                              ),
                              width: "MINIMIZE"
                            ),
                            #"SYSTEM_SYSRULES_sideBySideItem"(
                              item: #"SYSTEM_SYSRULES_richTextDisplayField"(
                                labelPosition: "COLLAPSED",
                                value: {
                                  #"SYSTEM_SYSRULES_richTextItem_v1"(
                                    text: {
                                      #"SYSTEM_SYSRULES_richTextItem_v1"(
                                        text: upper(
                                          user(loggedInUser(), "firstName") & " " & user(loggedInUser(), "lastName")
                                        ),
                                        size: "LARGE"
                                      ),
                                      char(10),
                                      #"SYSTEM_SYSRULES_forEach"(
                                        items: local!finalGroupsForUser,
                                        expression: {
                                          #"SYSTEM_SYSRULES_richTextIcon"(
                                            icon: "group", 
                                            size: "MEDIUM"
                                          ),
                                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                                            text: {
                                              " ",
                                              replace(
                                                fv!item,
                                                1,
                                                4,
                                                ""
                                              ),
                                              char(10)},
                                              color: "#FFFFFF",
                                              size: "MEDIUM"
                                          )
                                        }
                                      )
                                    },
                                    color: "#FFFFFF",
                                    size: "LARGE",
                                    style: "STRONG"
                                  )
                                },
                                align: "LEFT"
                              )
                            )
                          }
                        )
                      }
                    ),
                    #"SYSTEM_SYSRULES_columnLayout"(
                      contents: {
                        #"SYSTEM_SYSRULES_richTextDisplayField"(
                          labelPosition: "COLLAPSED",
                          value: {
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: { "DPP Recruiting Tool" },
                              color: "#FFFFFF",
                              size: "LARGE",
                              style: "STRONG"
                            ),
                            char(10),
                            char(10),
                            #"SYSTEM_SYSRULES_richTextIcon"(
                              icon: "plus",
                              link: #"SYSTEM_SYSRULES_startProcessLink"(
                                processModel: #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3641291",
                                processParameters: { isEdit: false }
                              ),
                              linkStyle: "STANDALONE",
                              showWhen: isusermemberofgroups(
                                loggedInUser(),
                                {
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922",
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177083",
                                  #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066240",
                                  #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066222",
                                  #"_a-0000e825-ace1-8000-9c24-011c48011c48_6814637",
                                  #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12648325",
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3176419",
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3176431",
                                  #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4625879",
                                  #"_a-0000e825-ace1-8000-9c24-011c48011c48_6790160",
                                  #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12362550"
                                }
                              )
                            ),
                            #"SYSTEM_SYSRULES_richTextItem_v1"(
                              text: " Create Nomination",
                              link: #"SYSTEM_SYSRULES_startProcessLink"(
                                processModel: #"_a-0000e6c7-249e-8000-9bfe-011c48011c48_3641291",
                                processParameters: { isEdit: false }
                              ),
                              linkStyle: "STANDALONE",
                              style: "STRONG",
                              showWhen: isusermemberofgroups(
                                loggedInUser(),
                                {
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3174922",
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177083",
                                  #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066240",
                                  #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066222",
                                  #"_a-0000e825-ace1-8000-9c24-011c48011c48_6814637",
                                  #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12648325",
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3176419",
                                  #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3176431",
                                  #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4625879",
                                  #"_a-0000e825-ace1-8000-9c24-011c48011c48_6790160",
                                  #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12362550"
                                }
                              )
                            )
                          },
                          align: "RIGHT"
                        )
                      }
                    )
                  }
                )
              }
            )
          }
        )
      },
      style: "SEMI_DARK"
    ),
    marginBelow: "LESS"
  )
)
